package com.threatstream.detection;
import java.util.*; import org.apache.kafka.clients.consumer.ConsumerConfig; import org.apache.kafka.common.serialization.StringDeserializer; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.kafka.core.*; import org.springframework.kafka.listener.DefaultErrorHandler; import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory; import org.springframework.kafka.support.serializer.JsonDeserializer;
@Configuration class NetworkKafkaConfiguration { @Bean ConcurrentKafkaListenerContainerFactory<String,NetworkEvent> networkKafkaListenerContainerFactory(@Value("${spring.kafka.bootstrap-servers}") String bootstrap,@Value("${spring.kafka.consumer.group-id}") String group,DefaultErrorHandler errors){Map<String,Object> p=new HashMap<>();p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG,bootstrap);p.put(ConsumerConfig.GROUP_ID_CONFIG,group);p.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG,false);p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG,"earliest");var d=new JsonDeserializer<>(NetworkEvent.class,false);d.addTrustedPackages("com.threatstream.detection");var f=new ConcurrentKafkaListenerContainerFactory<String,NetworkEvent>();f.setConsumerFactory(new DefaultKafkaConsumerFactory<>(p,new StringDeserializer(),d));f.getContainerProperties().setAckMode(org.springframework.kafka.listener.ContainerProperties.AckMode.RECORD);f.setCommonErrorHandler(errors);return f;} }
